draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var cx = W * 0.5, cy = H * 0.5;
var u = Math.min(W * 0.42, H * 0.44);
var rIn = u * 0.42, rOut = u * 0.68;

// metal shell
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.3;
ctx.beginPath();
ctx.arc(cx, cy, rOut, 0, Math.PI * 2);
ctx.arc(cx, cy, rIn, 0, Math.PI * 2, true);
ctx.fill();
ctx.globalAlpha = 1;
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, rOut, 0, Math.PI * 2); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, rIn, 0, Math.PI * 2); ctx.stroke();

// the charge in the cavity, off centre
var qx = cx - rIn * 0.45, qy = cy + rIn * 0.25;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(qx, qy, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", qx, qy + 4);

// induced signs
ctx.fillStyle = C.ink;
for (var i = 0; i < 12; i++) {
  var a = i * Math.PI / 6;
  ctx.fillText("-", cx + Math.cos(a) * (rIn + 9), cy + Math.sin(a) * (rIn + 9) + 4);
  ctx.fillText("+", cx + Math.cos(a) * (rOut - 9), cy + Math.sin(a) * (rOut - 9) + 4);
}

// gaussian surface drawn inside the metal
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.arc(cx, cy, (rIn + rOut) / 2, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

// outside field arrows
ctx.strokeStyle = C.rule; ctx.fillStyle = C.rule; ctx.lineWidth = 1.5;
for (var j = 0; j < 8; j++) {
  var b = j * Math.PI / 4 + 0.39;
  var sx = cx + Math.cos(b) * (rOut + 4), sy = cy + Math.sin(b) * (rOut + 4);
  var ex = cx + Math.cos(b) * (rOut + 20), ey = cy + Math.sin(b) * (rOut + 20);
  ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(ex, ey); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - Math.cos(b) * 7 - Math.sin(b) * 3.5, ey - Math.sin(b) * 7 + Math.cos(b) * 3.5);
  ctx.lineTo(ex - Math.cos(b) * 7 + Math.sin(b) * 3.5, ey - Math.sin(b) * 7 - Math.cos(b) * 3.5);
  ctx.closePath(); ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("E = 0 inside the metal", 8, 16);
ctx.fillText("inner wall: -q", 8, H - 20);
ctx.fillText("outer wall: +q, spread evenly", 8, H - 6);
ctx.textAlign = "center";
ctx.fillStyle = C.accent;
ctx.fillText("Gaussian surface encloses zero net charge", cx, cy - rOut - 6);
ctx.textAlign = "left";
